// Search the free list for the first block that is large enough
struct block *first_fit(struct block *free_list, int request_size) {
    struct block *cur = free_list;
    while (cur != NULL) {
        if (cur->size >= request_size) {
            return cur;   // stop at the very first block that fits
        }
        cur = cur->next;
    }
    return NULL;   // no block was large enough
}

